/* Independent timed practice. No responses or scores are sent over the network. */
(async function(){'use strict';
const M=globalThis.ILMastroMock,S=globalThis.ILMastroMockStore,data=globalThis.ILMASTRO_MOCK_DATA,host=document.getElementById('mock-app');if(!host||!data)return;
const owner=crypto.randomUUID(),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db,state=null,owns=false,blocked=false,pending=0,queue=Promise.resolve(),cursor=0,confirming=false,lastAnnounced='',loadedForm=M.readPresentation(data.form);
const channel=typeof BroadcastChannel==='function'?new BroadcastChannel('ilmastro-mock-state-v1'):null;
function announce(text){const n=document.getElementById('mock-save');if(n)n.textContent=text;}
function errorMessage(e){return /both-storage-unavailable/.test(e.message)?'両方の保存領域が利用できず、この画面を停止しました。未保存の入力も障害状態も他のタブへ引き継げません。すべてのタブでこの回を採点せず中断し、画面の入力を控えてください。':/other editor|stale revision/.test(e.message)?'別のタブがこの回を更新しました。回答を上書きせず停止しました。一覧へ戻り、再開するタブを選んでください。':/clock-regression/.test(e.message)?'端末の時計が戻ったため、この回を停止しました。期限を延ばして再開することはできません。':'保存を完了できませんでした。未保存の回答を成績へ含めず、この画面を停止しました。ページを閉じずに入力内容を控えてください。';}
function showError(message){blocked=true;host.querySelectorAll('input,select,button[data-edit]').forEach(x=>x.disabled=true);const n=document.getElementById('mock-error');if(n){n.hidden=false;n.textContent=message;n.focus();}announce('保存未完了・入力停止');}
function enqueue(operation,payload={},renderAfter=false){
 if(blocked||!owns)return Promise.resolve();pending++;announce('保存中…');
 const job=queue.then(async()=>{if(blocked||state.status!=='running')return;const next=await db.change(state.attemptId,owner,state.revision,operation,payload);state=next;channel?.postMessage({attemptId:state.attemptId,ownerId:state.ownerId,revision:state.revision});});
 queue=job.catch(e=>showError(errorMessage(e))).finally(()=>{pending--;if(!blocked&&pending===0){announce('保存済み');}if(!blocked&&(renderAfter||state?.status!=='running'))render();});return queue;
}
function layout(content){host.innerHTML='<div id="mock-error" class="mock-error" role="alert" tabindex="-1" hidden></div>'+content;}
function table(t){if(t.rows)return '<div class="mock-table" tabindex="0" role="region" aria-label="'+esc(t.title)+'"><table><caption>'+esc(t.title)+'</caption><thead><tr>'+t.headers.map(x=>'<th scope="col">'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+t.rows.map(row=>'<tr>'+row.map((x,i)=>'<'+(i?'td':'th scope="row"')+'>'+esc(x)+'</'+(i?'td':'th')+'>').join('')+'</tr>').join('')+'</tbody></table></div>';return '<section><h3>'+esc(t.title)+'</h3>'+((t.paragraphs||[]).map(p=>'<p>'+esc(p)+'</p>').join(''))+'</section>';}
function overview(){owns=false;confirming=false;const resumable=state?.status==='running',noticeForm=state?.form?M.readPresentation(state.form):loadedForm;layout('<h2 tabindex="-1">第1回 オリジナル総合練習</h2><p>日商簿記3級・2026年度範囲（2027年3月31日まで）</p><p><strong>60分 / 100点 / 第1問45点・第2問20点・第3問35点</strong></p><ul>'+noticeForm.notices.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><p class="scope-note">欄別配点・問題構成・解説はサイト独自です。公式試験と同等の難易度や採点ではなく、70点到達も合格予測ではありません。同じ問題の再受験は未見の力を測りません。途中再開しても期限は延長されません。保存障害時の未保存入力は復元できません。両方の保存領域が同時に利用不能になると、別タブへの障害通知も保証できません。</p><p>この端末・ブラウザ内に保存します。タブを切り替えるときは保存済み表示を確認してください。終了するまで正誤・解説は出しません。ソースには採点用データが含まれるため、不正防止付きの試験ではありません。</p>'+(state?.quarantined?'<p role="alert">'+esc(state.reason)+'</p>':'')+(state?.status==='recovery-blocked'?'<p role="alert">保存または時計の異常で前回の練習を停止しました。成績は確定していません。未保存入力は復元されません。</p>':'')+(resumable?'<p>途中の回があります。開始 '+esc(new Date(state.startedAt).toLocaleString('ja-JP'))+' / 期限 '+esc(new Date(state.expiresAt).toLocaleString('ja-JP'))+'</p>'+(state.inFlight?'<p role="alert">前回の回答保存または確定の完了を確認できません。この回は再開・採点せず、明示的に中断してください。</p>':'<button class="primary" data-action="resume">このタブで再開する</button>')+'<p>別タブの編集権を引き継ぎます。</p><button data-action="abandon">この回を中断する（成績は残しません）</button>':state?.result?'<p>前回 '+state.result.total+' / 100 点（独自採点）</p><button data-action="results">前回の結果を見る</button><button class="primary" data-action="start">同じ問題でもう一度練習する</button>':'<button class="primary" data-action="start">60分の練習を始める</button>')+'<p><a href="./">講義・反復演習へ戻る</a></p>');}
function inputField(f,value,prefix){const id=prefix+'-'+f.id;return '<label class="mock-input" for="'+esc(id)+'"><span>'+esc(f.label||f.id)+(f.unit?'（'+esc(f.unit)+'）':'')+'</span>'+(f.type==='choice'?'<select id="'+esc(id)+'" data-field="'+esc(f.id)+'"><option value="">選択してください</option>'+f.options.map(o=>'<option value="'+esc(o)+'"'+(String(value??'')===o?' selected':'')+'>'+esc(f.optionLabels?.[o]||o)+'</option>').join('')+'</select>':'<input id="'+esc(id)+'" data-field="'+esc(f.id)+'" inputmode="'+(f.signPolicy==='signed'?'decimal':'numeric')+'" type="text" maxlength="100" autocomplete="off" value="'+esc(value)+'">')+'</label>';}
function answerInputs(task,response){const spec=task.answerFormat;if(spec.type==='fields')return spec.fields.map(f=>inputField(f,response?.[f.id]??'',task.taskId)).join('');return Array.from({length:spec.maximumRows},(_,i)=>{const row=response?.[i]||{},p=task.taskId+'-row-'+i;return '<fieldset class="mock-row" data-row="'+i+'"><legend>仕訳 '+(i+1)+'行目</legend><label for="'+p+'-side">借方・貸方<select id="'+p+'-side" data-part="side"><option value="">未使用</option><option value="debit"'+(row.side==='debit'?' selected':'')+'>借方</option><option value="credit"'+(row.side==='credit'?' selected':'')+'>貸方</option></select></label><label for="'+p+'-account">勘定科目<select id="'+p+'-account" data-part="account"><option value="">未使用</option>'+spec.accounts.map(a=>'<option'+(a===row.account?' selected':'')+'>'+esc(a)+'</option>').join('')+'</select></label><label for="'+p+'-amount">金額（円）<input id="'+p+'-amount" data-part="amount" inputmode="numeric" type="text" maxlength="100" autocomplete="off" value="'+esc(row.amount||'')+'"></label></fieldset>';}).join('');}
function hasAnswer(task){const raw=state.responses[task.taskId];return !!raw&&(Array.isArray(raw)?raw.some(row=>Object.values(row).some(v=>String(v).trim()!=='')):Object.values(raw).some(v=>String(v).trim()!==''));}
function exercise(){const form=M.readPresentation(state.form),task=form.tasks[cursor];const flags=state.navigation?.flagged||[];
 layout('<div class="mock-status"><span>2026年度 / 独自配点</span><span class="mock-clock" role="timer" aria-live="off">残り <span id="mock-time"></span></span><span id="mock-save" role="status">'+(pending?'保存中…':'保存済み')+'</span></div><nav class="mock-nav" aria-label="設問の移動">'+form.tasks.map((t,i)=>'<button data-edit data-go="'+i+'" aria-current="'+(i===cursor)+'" aria-label="'+esc(t.title+(hasAnswer(t)?'・入力あり':'・未回答')+(flags.includes(t.taskId)?'・見直し':''))+'">'+(i<15?String(i+1):'第'+t.section+'問'+(t.section===2?'-'+(i-14):''))+(flags.includes(t.taskId)?' ★':'')+'</button>').join('')+'</nav><h2 id="mock-title" tabindex="-1">'+esc(task.title)+'</h2><p class="mock-question">'+esc(task.prompt)+'</p>'+task.exhibits.map(table).join('')+'<p class="scope-note">金額は円の整数。単位文字を入れないでください。未使用の仕訳行は全欄空欄にします。'+(task.policy?'仕訳全体一致で'+task.points+'点。':'指定グループの全欄一致で加点します。')+'</p><form id="mock-answer" novalidate>'+answerInputs(task,state.responses[task.taskId])+'</form><label class="mock-flag"><input type="checkbox" id="mock-flag"'+(flags.includes(task.taskId)?' checked':'')+'>あとで見直す</label><div class="mock-actions"><button data-edit data-action="save">保存する</button>'+(cursor>0?'<button data-edit data-go="'+(cursor-1)+'">前の設問</button>':'')+(cursor<form.tasks.length-1?'<button data-edit data-go="'+(cursor+1)+'">次の設問</button>':'')+'<button data-edit data-action="request-finish">回答を確定する</button></div><div id="mock-confirm"'+(confirming?'':' hidden')+'><p>未回答は0点です。一度確定すると、この回の答案は変更できません。</p><button data-edit class="primary" data-action="finish">この答案で確定する</button><button data-edit data-action="cancel-finish">まだ解く</button></div><p><button data-action="overview">保存して一覧へ</button></p>');tick();}
function answerText(task,ex){if(ex?.correctJournal)return '<ul>'+ex.correctJournal.map(r=>'<li>'+esc(r.side==='debit'?'借方':'貸方')+' '+esc(r.account)+' '+Number(r.amount).toLocaleString('ja-JP')+'円</li>').join('')+'</ul>';const spec=task.spec;return '<dl>'+spec.fields.map(f=>'<dt>'+esc(f.label||f.id)+'</dt><dd>'+esc(f.type==='choice'?(f.optionLabels?.[f.answer]||f.answer):Number(f.answer).toLocaleString('ja-JP',{maximumFractionDigits:f.decimals??0}))+(f.unit?' '+esc(f.unit):'')+'</dd>').join('')+'</dl>';}
function results(){const form=M.readPresentation(state.form),explanations=state.form.explanations;layout('<h2 tabindex="-1">練習結果・解説</h2><p><strong>'+state.result.total+' / 100 点</strong>（IL MASTRO独自採点）</p><p>第1問 '+state.result.sections[0]+'/45・第2問 '+state.result.sections[1]+'/20・第3問 '+state.result.sections[2]+'/35</p><p>'+esc(state.status==='timed-out'?'制限時間に達して確定しました。':'答案を確定しました。')+' 未回答は0点です。</p><p class="scope-note">70点はこの練習の目安です。本試験の合格判定・合格可能性・公式得点を示しません。同じ問題の再受験による点数上昇は未見問題の実力と区別してください。</p>'+state.form.tasks.map((t,i)=>{const ex=explanations.tasks.find(x=>x.taskId===t.taskId),result=state.result.tasks.find(x=>x.taskId===t.taskId);return '<details><summary>'+esc(form.tasks[i].title)+' — '+result.earned+'/'+result.max+'点</summary><p>'+esc(form.tasks[i].prompt)+'</p>'+form.tasks[i].exhibits.map(table).join('')+'<h3>あなたの保存済み回答</h3><pre>'+esc(JSON.stringify(state.responses[t.taskId]??(t.spec.type==='journal'?[]:{}),null,2))+'</pre><h3>正答</h3>'+answerText(t,ex)+'<ol>'+(ex?.steps||[]).map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol><p>'+esc(ex?.scoringNote||'サイト独自の配点です。')+'</p></details>';}).join('')+'<button data-action="overview">練習の一覧へ</button>');}
function render(){if(!state||!owns){overview();return;}if(state.result){results();return;}if(state.status!=='running'){layout('<h2>この回は停止しています</h2><p>保存・時計の状態を確認できないため成績を確定していません。</p><button data-action="overview">一覧へ</button>');return;}exercise();}
function raw(){const form=document.getElementById('mock-answer');if(!form)return null;const task=M.readPresentation(state.form).tasks[cursor];if(task.answerFormat.type==='journal')return [...form.querySelectorAll('[data-row]')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-part]')].map(x=>[x.dataset.part,x.value])));return Object.fromEntries([...form.querySelectorAll('[data-field]')].map(x=>[x.dataset.field,x.value]));}
function capture(){const response=raw();if(response!==null)return enqueue('save',{taskId:state.form.tasks[cursor].taskId,response});return queue;}
function focusTitle(){host.querySelector('h2')?.focus();}
function tick(){if(!owns||!state||state.status!=='running'||blocked)return;const remaining=Math.max(0,Math.ceil((state.expiresAt-db.time())/1000)),n=document.getElementById('mock-time');if(n)n.textContent=Math.floor(remaining/60)+':'+String(remaining%60).padStart(2,'0');if(db.clockRegressed()&&!pending)enqueue('heartbeat',{},true);else if(remaining===0&&!pending)enqueue('finish',{},true);}
host.addEventListener('submit',e=>{e.preventDefault();capture();});
host.addEventListener('input',e=>{if(e.target.closest('#mock-answer'))capture();});
host.addEventListener('change',e=>{if(e.target.id==='mock-flag'){const id=state.form.tasks[cursor].taskId,flags=new Set(state.navigation?.flagged||[]);e.target.checked?flags.add(id):flags.delete(id);enqueue('navigate',{cursor,flagged:[...flags]});}});
host.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const action=b.dataset.action;
 try{
  if(b.dataset.go!==undefined){await capture();if(blocked)return;const next=Number(b.dataset.go);await enqueue('navigate',{cursor:next,flagged:state.navigation?.flagged||[]});if(blocked)return;cursor=next;confirming=false;render();focusTitle();}
  else if(action==='start'){b.disabled=true;state=await db.start(data.form,owner);owns=true;blocked=false;cursor=0;render();focusTitle();}
  else if(action==='resume'){b.disabled=true;const old=state;state=await db.change(old.attemptId,owner,old.revision,'takeover');owns=true;cursor=state.navigation?.cursor||0;render();focusTitle();channel?.postMessage({attemptId:state.attemptId,ownerId:owner,revision:state.revision});}
  else if(action==='abandon'){b.disabled=true;state=await db.change(state.attemptId,owner,state.revision,'abandon');owns=false;blocked=false;render();focusTitle();}
  else if(action==='results'){owns=true;render();focusTitle();}
  else if(action==='save'){await capture();}
  else if(action==='request-finish'){await capture();if(blocked||state.status!=='running')return;confirming=true;document.getElementById('mock-confirm').hidden=false;host.querySelector('[data-action="finish"]').focus();}
  else if(action==='cancel-finish'){confirming=false;document.getElementById('mock-confirm').hidden=true;host.querySelector('[data-action="request-finish"]').focus();}
  else if(action==='finish'){b.disabled=true;await capture();await enqueue('finish',{},true);focusTitle();}
  else if(action==='overview'){if(owns&&!blocked)await capture();await queue;state=await db.current();owns=false;blocked=false;render();focusTitle();}
 }catch(err){showError(errorMessage(err));}
});
channel?.addEventListener('message',e=>{if(owns&&state?.status==='running'&&e.data.attemptId===state.attemptId&&e.data.ownerId!==owner)showError('別のタブがこの回を引き継ぎました。このタブからは回答を上書きしません。');});
addEventListener('beforeunload',e=>{if(pending){e.preventDefault();e.returnValue='';}});
addEventListener('pageshow',e=>{if(e.persisted){owns=false;blocked=false;db.current().then(s=>{state=s;render();}).catch(err=>showError(errorMessage(err)));}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&owns&&!blocked&&state?.status==='running')enqueue('heartbeat',{},false);});
setInterval(tick,1000);setInterval(()=>{if(owns&&!blocked&&!pending&&state?.status==='running')enqueue('heartbeat');},10000);
try{db=await S.openStore();state=await db.current();render();}catch(err){layout('<h2>時間制練習を開始できません</h2><p role="alert">このブラウザでは保存領域を利用できません。保存済みと誤表示しないため、時間制練習を開始していません。</p><p><a href="./">通常の講義・演習へ</a></p>');}
})();
